pub fn encode(allocator: mem.Allocator, s: []const u8) mem.Allocator.Error![]u8 {
    // Count alphanumeric characters
    var char_count: usize = 0;
    for (i, 0, s.len) |i| {
        const byte = s[i];
        if (std.ascii.isAlpha(byte) or std.ascii.isDigit(byte)) {
            char_count += 1;
        }
    }
    // Compute groups and spaces needed
    var groups: usize = (char_count + 4) / 5; // ceil division
    var spaces_needed: usize = groups; // include possible trailing space
    var result_len: usize = char_count + spaces_needed;
    // Allocate result buffer
    const result = try allocator.alloc(u8, result_len);
    // Fill result
    var pos = 0; // position in result
    var group_chars = 0; // chars written in current group
    for (i, 0, s.len) |i| {
        const byte = s[i];
        if (std.ascii.isAlpha(byte) or std.ascii.isDigit(byte)) {
            // encode
            const out_char: u8 = if (std.ascii.isAlpha(byte)) {
                const lower = std.ascii.toLower(byte);
                const offset = lower - 'a';
                const mapped = 'z' - offset;
                mapped
            } else {
                byte
            };
            // write
            result[pos] = out_char;
            pos += 1;
            group_chars += 1;
            if (group_chars == 5) {
                result[pos] = ' ';
                pos += 1;
                group_chars = 0;
            }
        }
    }
    // Remove trailing space if present
    if (pos > 0 and result[pos-1] == ' ') {
        pos -= 1;
    }
    // Return slice of actual length
    return result[0..pos];
}

